def find_solutions(x_max, n_max):
    solutions = []
    for n in range(2, n_max + 1):
        for x in range(n + 1, x_max + 1):
            val = x**n + x - 2
            if val <= 0:
                continue
            # Check if val is a power of 2
            if (val & (val - 1)) == 0:
                k = val.bit_length() - 1
                solutions.append((x, n, k))
    return solutions

print(find_solutions(1000, 20))

def check_k(k_max, n_max):
    solutions = []
    for k in range(1, k_max + 1):
        target = 2**k + 2
        for n in range(2, n_max + 1):
            # x is approximately target**(1/n)
            x = int(target**(1/n))
            # Check x and x+1 just in case of rounding
            for candidate_x in [x, x+1]:
                if candidate_x > n and candidate_x**n + candidate_x == target:
                    solutions.append((candidate_x, n, k))
    return solutions

print(check_k(1000, 100))

def find_solutions_x(x_max, n_max):
    solutions = []
    for x in range(3, x_max + 1):
        for n in range(2, min(x, n_max + 1)):
            val = x**n + x - 2
            if (val & (val - 1)) == 0:
                k = val.bit_length() - 1
                solutions.append((x, n, k))
    return solutions

print(find_solutions_x(1000, 10))

